-- Importação de Perdas & Quebras — período 01/08/2026 a 25/08/2026
-- Gerado a partir dos relatórios 'quebra_ate_2508.pdf' (perecíveis) e
-- 'quebra_seca_ate_2508.pdf' (demais setores) da loja 327.
--
-- Como rodar: SQL Editor do Supabase → New query → cola tudo isso → Run.
-- (roda por cima sem duplicar: se rodar de novo, só atualiza os valores)

on conflict (loja, periodo_inicio, periodo_fim, produto_cod) do update set
  setor = excluded.setor,
  sortimento = excluded.sortimento,
  produto = excluded.produto,
  unidade = excluded.unidade,
  quantidade = excluded.quantidade,
  valor_perdido = excluded.valor_perdido,
  valor_vendido = excluded.valor_vendido,
  pct_perda = excluded.pct_perda,
  importado_em = now();
